#include <iostream>

using namespace std;

int main()
{
    int num;
    while (true)
    {
        cout << "Enter a number: ";
        cin >> num;
        if (num == 0)
        {
            cout << "exit...";
            break;
        }
        if (num % 2 == 0)
        {
            cout << "Even\n";
        }
        else
        {
            cout << "odd\n";
        }
    }
}

#include <iostream>

using namespace std;

int main()
{
    int min, max;
    cout << "Enter min number:";
    cin >> min;
    cout << "Enter max number:";
    cin >> max;
    for (int i = min; i <= max; i += 2)
    {
        cout << i * i << " ";
    }
    cout << endl;
}
